import './style.css';
import {initializeApp} from 'firebase/app';
import {getAuth,connectAuthEmulator,setPersistence,browserLocalPersistence,browserSessionPersistence,onAuthStateChanged,createUserWithEmailAndPassword,signInWithEmailAndPassword,sendEmailVerification,sendPasswordResetEmail,updateProfile,signOut,reload,multiFactor,TotpMultiFactorGenerator,getMultiFactorResolver} from 'firebase/auth';
import {getFunctions,connectFunctionsEmulator,httpsCallable} from 'firebase/functions';
const root=document.querySelector('#app');
import {accountGate, safeDestination, validateRegistration} from './account-flow.js';
import {resolveFirebaseConfig} from './firebase-config.js';
const env=import.meta.env ?? {};
const cfg=resolveFirebaseConfig(env);
const emulator=env.VITE_EMULATOR==='true';
let auth,fn,user=null,me=null,ready=false,routeRun=0,mfaResolver=null,totpSecret=null,authBusy=false,destination='dashboard';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=s=>String(s||'').replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const badge=s=>`<span class="badge ${esc(s)}">${esc(label(s))}</span>`;
const date=n=>n?new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Accra',dateStyle:'medium',timeStyle:'short'}).format(new Date(n))+' GMT':'—';
const href=(r,t,cls='btn')=>`<a class="${cls}" href="#${esc(r)}">${esc(t)}</a>`;
const btn=(t,cls='btn primary')=>`<button class="${cls}" type="submit">${esc(t)}</button>`;
const field=(name,text,value='',type='text',required=true,extra='')=>`<label class="field">${esc(text)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;
const area=(n,t,v='')=>`<label class="field">${esc(t)}<textarea name="${n}" required>${esc(v)}</textarea></label>`;
const select=(n,t,opts,selected='')=>`<label class="field">${esc(t)}<select name="${n}" required><option value="">Choose…</option>${opts.map(([k,v])=>`<option value="${esc(k)}" ${k===selected?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
const form=(op,body,submit='Save',extra='')=>`<form class="form" data-op="${op}" ${extra}>${body}${btn(submit)}</form>`;
const head=(tag,title,desc='')=>`<div class="eyebrow">${esc(tag)}</div><h1>${esc(title)}</h1><p class="muted">${esc(desc)}</p>`;
const box=(title,body)=>`<section class="card"><h2>${esc(title)}</h2>${body}</section>`;
const deadline=()=>`<div class="deadline"><div><div class="eyebrow" id="deadlineLabel">Application deadline</div><strong>26 November 2026 · 11:59 PM GMT</strong><small>Applications close automatically at midnight.</small></div><div id="clock" class="clock"></div></div>`;
const staff=()=>['admin','super'].includes(me?.role);
const route=()=>location.hash.slice(1)||'home';
function go(r){if(route()===r)render();else location.hash=r;}
function resume(){const next=safeDestination(destination);destination='dashboard';go(next);}
function requireLogin(next){destination=safeDestination(next);go('login');}
const passwordField=(name,text,extra='')=>`<div class="password-wrap">${field(name,text,'','password',true,extra)}<button type="button" class="btn password-toggle" data-action="passwordToggle" data-field="${name}" aria-label="Show ${esc(text.toLowerCase())}" aria-pressed="false">Show</button></div>`;
const api=async(op,values={})=>{
 const publicOp=['catalogue','health','readiness'].includes(op),uid=auth.currentUser?.uid;
 if(!publicOp&&!uid)throw Error('Create an account and sign in first.');
 try{
  const result=await httpsCallable(fn,'portal',{timeout:op==='upload'||op==='download'?90000:45000})({...values,op});
  if(!publicOp&&auth.currentUser?.uid!==uid)throw Error('Your session changed. Sign in again.');
  return result.data;
 }catch(e){e.portalOperation=op;throw e;}
};
function message(m,bad=false){const el=document.querySelector('#message');if(el){el.textContent=m;el.className='notice'+(bad?' error':'');el.scrollIntoView({block:'nearest'});}}
function error(e){const messages={'auth/invalid-credential':'Incorrect email or password. Please try again.','auth/email-already-in-use':'This email already has an account. Sign in or reset your password.','auth/weak-password':'Choose a stronger password.','auth/too-many-requests':'Too many attempts. Try again later.','auth/network-request-failed':'Connection failed. Check your internet and try again.','auth/operation-not-allowed':'Email/password sign-in is not enabled. Contact the administrator.','auth/user-disabled':'This account is disabled. Contact the administrator.'};const code=e?.code;
 const support=typeof e?.details?.supportReference==='string'&&/^ERR-[A-F0-9]{12}$/.test(e.details.supportReference)?' Support reference: '+e.details.supportReference+'.':'';
 const generic=code==='functions/internal'&&(!e.message||/^internal$/i.test(e.message))?'The Firebase backend returned an internal error. Check the deployed portal function and its logs.':code==='functions/not-found'&&(!e.message||/^not[- ]found$/i.test(e.message))?'The Firebase portal function could not be reached. Check its deployment in us-central1.':code==='functions/deadline-exceeded'?'The backend request timed out. Check connectivity and try again.':null;
 return (messages[code]||generic||String(e?.message||'Request failed. Please try again.').replace(/^Firebase: /,''))+support;
}
function frame(body,inside=false){const brand=`<a class="brand" href="#${inside?'dashboard':'home'}"><span class="logo"><img src="data:image/jpeg;base64," alt="NPP emblem"></span><span>AEE / APPOINTMENTS<small>Ajumako-Enyan-Essiam Constituency</small></span></a>`;let links=[];if(inside){links=staff()?[['dashboard','Overview'],['applications','Applications'],['sessions','Vetting'],['reports','Reports'],['vacancies','Positions'],['account','Account']]:me?.role==='panel'?[['dashboard','Overview'],['sessions','Vetting'],['account','Account']]:[['dashboard','Overview'],['positions','Available positions'],['applications','My applications'],['notifications','Notifications'],['account','Account']];}root.innerHTML=`<header class="top">${brand}<nav class="nav">${inside?`<span>${esc(me?.profile?.name||'Account')}</span><button class="btn" data-action="logout">Sign out</button>`:`${href('home','Home','')}${href('positions','Positions','')}${user?href('dashboard','Dashboard','btn primary'):`${href('login','Sign in · Staff / Applicant','')}${href('register','Create account','btn primary')}`}`}</nav></header>${inside?`<div class="layout"><aside><div class="eyebrow">Workspace</div>${links.map(([r,t])=>href(r,t,route().split('/')[0]===r?'active':'')).join('')}</aside><section class="content">`:'<section class="public">'}<div id="message" role="status" class="hidden"></div>${body}<div class="footer">NPP-AEEC · Ghana / GMT · ${href('privacy','Privacy information','')}</div></section>${inside?'</div>':''}`;tick();}
function tick(){const el=document.querySelector('#clock');if(!el)return;const sec=Math.max(0,Math.floor((Date.parse('2026-11-27T00:00:00Z')-Date.now())/1000));el.textContent=sec?`${Math.floor(sec/86400)}d  ${Math.floor(sec/3600)%24}h  ${Math.floor(sec/60)%60}m  ${sec%60}s`:'Closed';if(!sec)document.querySelector('#deadlineLabel').textContent='Applications closed';}
function appTable(rows){return `<div class="table"><table><thead><tr><th>Reference</th>${staff()?'<th>Applicant</th>':''}<th>Position</th><th>Status</th><th></th></tr></thead><tbody id="appRows">${rows.map(r=>`<tr data-search="${esc([r.reference||'Draft',r.name,r.title].join(' ').toLowerCase())}" data-status="${esc(r.status)}"><td>${esc(r.reference||'Draft')}</td>${staff()?`<td>${esc(r.name)}</td>`:''}<td>${esc(r.title)}</td><td>${badge(r.status)}</td><td>${href('application/'+r.id,'Open →')}</td></tr>`).join('')||'<tr><td colspan="5">No applications yet.</td></tr>'}</tbody></table></div>`;}
function metric(n,v){return `<div class="metric"><span>${esc(n)}</span><strong>${esc(v)}</strong></div>`;}
async function render(){const serial=++routeRun;const r=route(),[page,param]=r.split('/');const show=(body,inside=false)=>{if(serial===routeRun)frame(body,inside);};
 try{
 if(!ready)return;
 if(page==='connection'){
  show(head('Connection check','Checking Firebase services','This diagnostic does not display application or account records.')+'<p>Testing the connection…</p>');
  const checks=[];
  const check=async(name,operation,validate=()=>true)=>{try{const result=await api(operation);if(!validate(result))throw Error('Unexpected or outdated backend response. Deploy the matching v7.2 Cloud Functions.');checks.push([name,'Connected']);return true;}catch(e){checks.push([name,error(e)]);return false;}};
  const alive=await check('Cloud Functions (us-central1)','health',r=>r.ok===true&&r.release==='7.2.0');
  if(alive){await check('Firestore catalogue','catalogue',r=>Array.isArray(r.positions));await check('Firestore and private Storage readiness','readiness',r=>r.ok===true&&r.firestore===true&&r.storage===true);if(user?.emailVerified)await check('Private account access','me',r=>r.uid===user.uid);else checks.push(['Private account access','Sign in with a verified account to test.']);}
  else checks.push(['Firestore and account access','Not tested. Deploy the current backend first.']);
  show(head('Connection check','Firebase service status','No applicant records are displayed or exported here.')+box('Results',checks.map(([name,result])=>`<div class="step"><b>${esc(name)}</b><p>${esc(result)}</p></div>`).join(''))+`<div class="row">${href('home','Home')} ${href(user?'dashboard':'login',user?'Dashboard':'Sign in')} <button class="btn primary" data-action="retry">Run checks again</button></div>`);return;
 }
 if(page==='privacy'){show(head('Privacy','Privacy information','Applicant records are restricted to the applicant and authorised staff.')+box('Data use','<p>Account and application data are used to process the appointment exercise. Do not include unrelated sensitive information in documents. Access is restricted and logged. Contact the authorised constituency administrator for correction, retention or deletion requests. The operator must publish its approved privacy notice before accepting real applications.</p>'),!!me?.profile);return;}
 if(page==='home'){show(deadline()+`<section class="hero"><div><div class="eyebrow">2026 · Constituency recruitment</div><h1>Constituency appointment portal.</h1><p>Browse available positions, create your personal account, sign in and submit your application securely. No guest applications are accepted.</p><div class="row">${href('positions','View positions →','btn red')}${href(user?'dashboard':'register',user?'My dashboard':'Create account','btn')}</div></div><div class="flow"><div>01 · Select a position</div><div>02 · Submit details and documents</div><div>03 · Review and vetting</div><div>04 · Track your decision</div></div></section>`);return;}
 if(page==='positions'){show(head('Recruitment','Available positions','Fetching the published positions securely…'));let c;try{c=await api('catalogue');}catch(e){show(head('Recruitment','Available positions','Live availability could not be loaded. No application can be submitted from this screen until Firebase reconnects.')+deadline()+box('Live connection required',`<p>${esc(error(e))}</p><div class="row">${href('connection','Check connection')} <button class="btn primary" data-action="retry">Retry catalogue</button> ${href(user?'dashboard':'login',user?'Open dashboard':'Sign in')}</div>`));return;}show(head('Recruitment','Available positions','An account and verified email are required to apply. Existing applicants must sign in.')+deadline()+`<div class="grid">${c.positions.map(v=>box(v.title,`${badge(v.open?'open':'closed')}<p class="pre">${esc(v.description||'See the approved document requirements below.')}</p><p>${esc(v.requirements.join(' · ')||'No additional documents listed.')}</p>${v.open?(user&&me?.role==='applicant'&&me.profile?`<button class="btn primary" data-action="apply" data-id="${esc(v.id)}">Apply →</button>`:(user?href('dashboard','Complete account','btn primary'):`${href('register','Create account to apply','btn primary')} ${href('login','Already registered? Sign in')}`)):''}`)).join('')||'<p>No published positions.</p>'}</div>`,!!me?.profile);return;}
 if(page==='login'||page==='register'||page==='reset'){
  if(user){resume();return;}
  const reg=page==='register',reset=page==='reset';
  show(`<div class="narrow card auth-card">${head('Secure applicant account',reset?'Recover password':reg?'Create your account':'Welcome back',reset?'Enter your registered email address.':reg?'Register once, then verify your email to apply.':'Applicants and administrators use their registered Firebase email and password. Staff access is assigned securely by account UID.')}${form(page,(reg?field('name','Full name','','text',true,'autocomplete="name" maxlength="150"'):'')+field('email','Email address','','email',true,'autocomplete="email"')+(!reset?passwordField('password','Password',reg?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"'):'')+(reg?passwordField('confirmPassword','Confirm password','minlength="12" autocomplete="new-password"')+'<small>Use at least 12 characters.</small><label class="check"><input type="checkbox" name="consent" required> I have read the <a href="#privacy" target="_blank" rel="noopener">privacy information</a> and agree to account registration.</label>':'')+(!reset?'<label class="check"><input type="checkbox" name="remember"> Keep me signed in on this private device</label>':''),reset?'Send reset email':reg?'Create account':'Sign in')}<div class="row subhead">${!reset&&!reg?href('reset','Forgot password?',''):''}${href(reg||reset?'login':'register',reg||reset?'Already registered? Sign in':'New applicant? Create account','')}</div></div>`);return;
 }
 const gate=accountGate({route:r,user,mfaPending:!!mfaResolver});
 if(page==='mfa'){if(gate!=='mfa'){go('login');return;}show(`<div class="narrow card">${head('Secure account','Two-factor verification')}${form('mfa',field('code','Authenticator code','','text',true,'inputmode="numeric" pattern="[0-9]{6}"'),'Verify')}<button class="btn" data-action="cancelMfa">Back to sign in</button></div>`);return;}
 if(gate==='login'){requireLogin(r);return;}
 if(gate==='verify'){show(`<div class="narrow card">${head('Secure account','Verify your email','Check your inbox and spam folder. Open the verification link, then return here. You cannot submit an application until verified.')}<p>${esc(user.email)}</p><div class="row"><button class="btn primary" data-action="verify">I have verified</button><button class="btn" data-action="resend">Resend email</button><button class="btn" data-action="logout">Sign out</button></div></div>`);return;}
 if(page==='security'){show(`<div class="narrow card">${head('Account security','Set up authenticator','Staff must use an authenticator app. Reauthenticate first if Firebase requests it.')}<button class="btn primary" data-action="totp">Generate setup key</button><div id="enrol"></div><p class="subhead"><button class="btn" data-action="logout">Sign out</button></p></div>`);return;}
 if(!me){show(head('Secure account','Checking your account','Verifying your access to the portal…'));try{const result=await api('me');if(serial!==routeRun)return;me=result;}catch(e){if(serial!==routeRun)return;if(error(e).includes('multifactor')){go('security');return;}throw e;}}
 if(!me.profile){show(`<div class="narrow card">${head('Secure profile','Complete your profile')}${form('profile',field('name','Full name',user.displayName||'','text',true,'maxlength="150" autocomplete="name"')+'<label class="check"><input type="checkbox" name="consent" required> I understand the <a href="#privacy" target="_blank" rel="noopener">privacy information</a> and consent to processing this application.</label>','Continue')}</div>`);return;}
 if(page==='dashboard'){if(staff()){const s=await api('summary');const total=Object.values(s.counts).reduce((x,y)=>x+y,0);show(head('Administration','Recruitment overview','Private management workspace.')+deadline()+`<div class="grid">${metric('Total submissions',total)}${metric('Awaiting review',s.counts.submitted)}${metric('Under review',s.counts.under_review)}${metric('Vetting scheduled',s.counts.vetting_scheduled)}</div><div class="grid">${box('Recruitment pipeline',Object.entries(s.counts).map(([k,v])=>`<div class="spread"><small>${esc(label(k))}</small><b>${v}</b></div><div class="progress"><i style="width:${total?v/total*100:0}%"></i></div>`).join(''))}${box('New application alerts',`<div class="scroll">${s.alerts.map(x=>`<div class="step"><b>${esc(x.reference)}</b><p>${esc(date(x.at))}</p>${href('application/'+x.application,'Open securely →')}</div>`).join('')||'<p>No submissions yet.</p>'}</div><div class="row subhead">${href('applications','Application register','btn primary')}${href('sessions','Schedule vetting')}</div>`)}</div>`,true);}
 else if(me.role==='panel'){show(head('Vetting panel','Panel workspace','Review only your assigned sessions.')+href('sessions','Assigned sessions','btn primary'),true);}
 else{const a=await api('applications');show(head('Applicant','My dashboard','Track your applications and vetting invitations.')+deadline()+`<div class="grid">${metric('Applications on this page',a.rows.length)}${metric('Submitted on this page',a.rows.filter(x=>x.submitted).length)}</div>`+box('My applications',appTable(a.rows)+href('positions','Choose a position','btn primary')),true);}return;}
 if(page==='applications'){const a=await api('applications',{cursor:param||null});show(head('Workspace',staff()?'Application register':'My applications','Search and filter the current page of records.')+box('Applications',`<div class="toolbar"><input type="search" id="query" placeholder="Search reference, name or position" aria-label="Search"><select id="statusFilter" aria-label="Status"><option value="">All statuses</option>${[...new Set(a.rows.map(x=>x.status))].map(s=>`<option value="${esc(s)}">${esc(label(s))}</option>`).join('')}</select></div>${appTable(a.rows)}<div class="row subhead">${param?href('applications','First page'):''}${a.next?href('applications/'+a.next,'Next page →'):''}</div>`),true);return;}
 if(page==='application'){const a=await api('application',{id:param});const editable=me.role==='applicant'&&['draft','changes_requested'].includes(a.status);const hid=`data-id="${esc(a.id)}"`;let content=head('Application',a.reference||'Draft application',a.title)+`<div class="row">${badge(a.status)}<small>Updated ${esc(date(a.updated))}</small></div>`;
 content+=box('Applicant details',`<p><b>${esc(a.name)}</b><br>${esc(a.email)}</p>${editable?form('draftSave',field('phone','Phone (optional)',a.phone,'tel',false)+area('qualifications','Qualifications',a.qualifications)+area('experience','Relevant experience',a.experience),'Save details',hid):`<p>${esc(a.phone)}</p><h3>Qualifications</h3><p class="pre">${esc(a.qualifications)}</p><h3>Experience</h3><p class="pre">${esc(a.experience)}</p>`}`);
 content+=box('Documents',a.requirements.map(l=>{const f=a.documents.find(x=>x.label===l);return `<div class="step"><b>${esc(l)}</b><p>${f?esc(f.name)+' '+badge(f.scan):'Not attached'}</p>${f?.scan==='clean'?`<button class="btn" data-action="download" data-id="${esc(a.id)}" data-file="${esc(f.id)}">Download privately</button>`:''}${editable?form('upload',`<input type="hidden" name="label" value="${esc(l)}"><label class="field">Choose PDF, JPG or PNG (max 5 MB)<input name="file" type="file" accept=".pdf,.jpg,.jpeg,.png" required></label>`,'Upload',hid):''}</div>`;}).join('')||'<p>No documents specified.</p>');
 if(editable)content+=box('Review and submit',`<p>Save details before submitting. Uploaded documents remain quarantined until security checks pass.</p>${form('submit','<label class="check"><input type="checkbox" name="declaration" required> I confirm that the information and documents are accurate.</label>','Submit application',hid)}`);
 if(a.vetting)content+=box('Vetting appointment',`<p><b>${esc(a.vetting.title)}</b><br>${esc(date(a.vetting.start))} – ${esc(date(a.vetting.end))}<br>${esc(a.vetting.venue)}</p><p>Attendance: ${esc(label(a.attendance))}</p>`);
 if(staff()){const moves={under_review:['changes_requested','approved_for_vetting','rejected_before_vetting'],vetting_scheduled:['vetted'],vetted:['decision_pending'],decision_pending:me.authority?['appointed','reserve_list','unsuccessful']:[]}[a.status]||[];if(moves.length)content+=box('Review decision',form('transition',select('status','Next status',moves.map(x=>[x,label(x)]))+area('reason','Reason (visible to applicant)')+(a.status==='under_review'?field('correctionDeadline','Correction deadline, GMT (if requesting changes)','','datetime-local',false):''),'Save status',hid));
 if(['approved_for_vetting','vetting_scheduled'].includes(a.status)){const sessions=await api('sessions');content+=box('Schedule vetting',form('schedule',select('session','Vetting session',sessions.filter(x=>x.start>Date.now()).map(x=>[x.id,x.title+' · '+date(x.start)])),'Assign / reschedule',hid)+href('sessions','Manage sessions'));}
 if(a.status==='vetting_scheduled')content+=box('Attendance',form('attendance',select('value','Attendance',[['present','Present'],['absent','Absent'],['excused','Excused']],a.attendance),'Save attendance',hid));
 if(a.session){const assessments=await api('assessments',{id:a.id});content+=box('Panel assessments',assessments.map(x=>`<div class="step"><b>Score: ${esc(x.score)} / 100</b><p class="pre">${esc(x.note)}</p></div>`).join('')||'<p>No assessments yet.</p>');}}
 if(me.role==='panel'&&a.status==='vetting_scheduled'&&a.attendance==='present')content+=box('Assessment',form('assessment',field('score','Score out of 100','','number',true,'min="0" max="100" step="1"')+area('note','Recommendation'),'Submit final assessment',hid));
 if(me.role==='applicant'&&['draft','submitted','under_review','changes_requested','approved_for_vetting'].includes(a.status))content+=box('Withdraw application',`<button class="btn danger" data-action="withdraw" data-id="${esc(a.id)}">Withdraw</button>`);
 content+=box('Status history',(a.history||[]).map(x=>`<div class="step">${badge(x.status)} <small>${esc(date(x.at))}</small>${x.reason?`<p class="pre">${esc(x.reason)}</p>`:''}</div>`).join('')||'<p>Draft not yet submitted.</p>');show(content,true);return;}
 if(page==='sessions'){const sessions=await api('sessions');let content=head('Vetting','Vetting sessions','Dates and times use Ghana GMT.');if(staff()){const panels=await api('panelList');content+=box('Create session',form('sessionCreate',field('title','Session name')+field('venue','Venue')+field('start','Start (GMT)','','datetime-local')+field('end','End (GMT)','','datetime-local')+field('capacity','Capacity','10','number',true,'min="1" max="100"')+`<label class="field">Panel members (select one or more)<select name="panel" multiple>${panels.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label>`,'Create session'));}content+=`<div class="grid">${sessions.map(s=>box(s.title,`<p>${esc(date(s.start))} – ${esc(date(s.end))}<br>${esc(s.venue)}</p><p>${s.applications.length} / ${s.capacity} assigned</p>${s.applications.map(i=>href('application/'+i,'Open assigned application')).join(' ')}`)).join('')||'<p>No sessions available.</p>'}</div>`;show(content,true);return;}
 if(page==='reports'){const s=await api('summary');const daily=await api('dailyReports');show(head('Administration','Recruitment reports','Aggregate totals only. No personal data is exported here.')+box('Status summary',Object.entries(s.counts).map(([k,v])=>`<div class="spread step"><span>${esc(label(k))}</span><b>${v}</b></div>`).join('')+'<button class="btn primary" data-action="report">Download CSV summary</button>')+box('Automatic daily summaries · 18:00 GMT',daily.map(x=>`<div class="step"><b>${esc(x.day)}</b><p>${Object.entries(x.counts).map(([k,v])=>esc(label(k))+': '+esc(v)).join(' · ')}</p></div>`).join('')||'<p>No scheduled snapshots yet.</p>'),true);return;}
 if(page==='vacancies'){const v=await api('vacancies');show(head('Recruitment','Position management','Administrators can manage approved public requirements.')+`<div class="grid">${v.map(x=>box(x.title,staff()?form('vacancySave',area('description','Public description',x.description||'')+`<label class="field">Required document labels (one per line)<textarea name="requirements">${esc(x.requirements.join('\n'))}</textarea></label><label class="check"><input type="checkbox" name="published" ${x.published?'checked':''}> Published</label>`,'Save position',`data-id="${esc(x.id)}"`):badge(x.published?'published':'closed'))).join('')}</div>`,true);return;}
 if(page==='notifications'){const n=await api('notifications');show(head('Workspace','Notifications','Private application updates.')+box('Inbox',n.map(x=>`<div class="step"><p>${esc(x.message)}</p><small>${esc(date(x.at))}</small><div class="row">${href('application/'+x.ref,'Open')}${!x.read?`<button class="btn" data-action="read" data-id="${esc(x.id)}">Mark read</button>`:''}</div></div>`).join('')||'<p>No notifications.</p>'),true);return;}
 if(page==='account'){show(head('Account','My profile')+box('Profile',form('profile',field('name','Full name',me.profile.name)+`<p>${esc(me.email)}</p>`,'Save profile')+`<p class="subhead">${href('security','Authenticator setup')} <button class="btn" data-action="password">Send password reset email</button></p>`),true);return;}
 go('dashboard');
 }catch(e){if(serial!==routeRun)return;const operation=e.portalOperation||'page';const code=typeof e.code==='string'?e.code:'client/error';console.warn('Portal request failed',{operation,code});show(head('Request not completed','Unable to open this page',error(e))+`<p class="muted">Diagnostic: ${esc(operation)} · ${esc(code)}</p><div class="row">${href('home','Home')} <button class="btn primary" data-action="retry">Try again</button> ${href('connection','Check connection')} ${user?'<button class="btn" data-action="logout">Sign out</button>':''}</div>`,!!me?.profile);}}
function values(f){return Object.fromEntries(new FormData(f));}
const gmt=s=>s?Date.parse(s+'Z'):null;
function base64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.readAsDataURL(file);});}
function download(b,name,type){const u=URL.createObjectURL(new Blob([b],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
root.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('form[data-op]'))return;e.preventDefault();const op=f.dataset.op,v=values(f),b=f.querySelector('button[type=submit]');b.disabled=true;try{
 if(op==='register'){
  const problem=validateRegistration(v);if(problem)throw Error(problem);
  authBusy=true;
  try{await setPersistence(auth,v.remember?browserLocalPersistence:browserSessionPersistence);const u=await createUserWithEmailAndPassword(auth,v.email.trim(),v.password);user=u.user;me=null;let warning='';try{await updateProfile(u.user,{displayName:v.name.trim()});}catch{warning='Your account exists. Enter your name when completing your profile.';}try{await sendEmailVerification(u.user);}catch{warning+=' Verification email could not be sent. Use Resend email.';}authBusy=false;history.replaceState(null,'','#'+safeDestination(destination));await render();if(warning)message(warning.trim(),true);return;}finally{authBusy=false;}
 }
 if(op==='login'){authBusy=true;try{await setPersistence(auth,v.remember?browserLocalPersistence:browserSessionPersistence);const result=await signInWithEmailAndPassword(auth,v.email.trim(),v.password);user=result.user;me=null;resume();}catch(ex){if(ex.code!=='auth/multi-factor-auth-required')throw ex;mfaResolver=getMultiFactorResolver(auth,ex);go('mfa');}finally{authBusy=false;}return;}
 if(op==='mfa'){const h=mfaResolver?.hints.find(x=>x.factorId===TotpMultiFactorGenerator.FACTOR_ID);if(!h)throw Error('No TOTP authenticator enrolled. Contact administrator.');authBusy=true;try{const result=await mfaResolver.resolveSignIn(TotpMultiFactorGenerator.assertionForSignIn(h.uid,v.code));user=result.user;me=null;mfaResolver=null;resume();}finally{authBusy=false;}return;}
 if(op==='reset'){try{await sendPasswordResetEmail(auth,v.email.trim());}catch(e){if(e.code!=='auth/user-not-found')throw e;}message('If the account exists, a reset email has been requested.');return;}
 if(op==='enrol'){await multiFactor(user).enroll(TotpMultiFactorGenerator.assertionForEnrollment(totpSecret,v.code),'Authenticator');totpSecret=null;await signOut(auth);go('login');return;}
 if(op==='profile'){await api(op,{name:v.name,consent:!!v.consent});me=await api('me');if(route()==='account'){await render();message('Profile saved.');}else if(destination!=='dashboard')resume();else if(route()==='dashboard')await render();else await render();return;}
 if(f.dataset.id)v.id=f.dataset.id;if(op==='sessionCreate'){v.start=gmt(v.start);v.end=gmt(v.end);v.panel=new FormData(f).getAll('panel');}if(op==='transition')v.correctionDeadline=gmt(v.correctionDeadline);if(op==='vacancySave'){v.requirements=v.requirements.split('\n').map(s=>s.trim()).filter(Boolean);v.published=!!v.published;}if(op==='submit')v.declaration=!!v.declaration;if(op==='upload'){if(!v.file||v.file.size>5*1024*1024)throw Error('Select a file no larger than 5 MB.');v.name=v.file.name;v.base64=await base64(v.file);delete v.file;}
 const result=await api(op,v);await render();message(op==='submit'?'Application received: '+result.reference:'Saved successfully.');
 }catch(ex){message(error(ex),true);}finally{b.disabled=false;}});
root.addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b)return;b.disabled=true;try{const a=b.dataset.action;if(a==='retry'){me=null;await render();return;}if(a==='passwordToggle'){const input=b.closest('.password-wrap').querySelector('input');const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',(show?'Hide ':'Show ')+input.name);return;}if(a==='cancelMfa'){mfaResolver=null;go('login');return;}if(a==='logout'){destination='dashboard';mfaResolver=null;totpSecret=null;await signOut(auth);me=null;go('home');return;}if(a==='verify'){await reload(user);await user.getIdToken(true);me=null;if(!user.emailVerified){message('Email is not verified yet. Open the link in your inbox and try again.',true);return;}await render();return;}if(a==='resend'){await sendEmailVerification(user);message('Verification email requested.');return;}if(a==='password'){await sendPasswordResetEmail(auth,user.email);message('Password reset email requested.');return;}if(a==='totp'){totpSecret=await TotpMultiFactorGenerator.generateSecret(await multiFactor(user).getSession());document.querySelector('#enrol').innerHTML=`<p class="notice">Enter this setup key in your authenticator app. Keep it private.</p><p class="pre"><b>${esc(totpSecret.secretKey)}</b></p>${form('enrol',field('code','Six-digit code','','text',true,'inputmode="numeric" pattern="[0-9]{6}"'),'Enable authenticator')}`;return;}if(a==='apply'){const r=await api('createDraft',{position:b.dataset.id});go('application/'+r.id);return;}if(a==='download'){const r=await api('download',{id:b.dataset.id,fileId:b.dataset.file});download(Uint8Array.from(atob(r.base64),c=>c.charCodeAt(0)),r.name,r.type);return;}if(a==='withdraw'){if(!confirm('Withdraw this application? This cannot be undone.'))return;await api('withdraw',{id:b.dataset.id});}if(a==='read')await api('notificationRead',{id:b.dataset.id});if(a==='report'){const s=await api('summary');download('Status,Count\n'+Object.entries(s.counts).map(([k,v])=>`${k},${v}`).join('\n'),'NPP-AEEC-summary.csv','text/csv');return;}await render();}catch(ex){message(error(ex),true);}finally{b.disabled=false;}});
function filter(){const q=(document.querySelector('#query')?.value||'').toLowerCase(),s=document.querySelector('#statusFilter')?.value||'';document.querySelectorAll('#appRows tr[data-search]').forEach(r=>r.hidden=!r.dataset.search.includes(q)||!!s&&r.dataset.status!==s);}
root.addEventListener('input',e=>{if(e.target.id==='query')filter();});root.addEventListener('change',e=>{if(e.target.id==='statusFilter')filter();});
window.addEventListener('hashchange',render);setInterval(tick,1000);setInterval(()=>{if(ready&&me&&staff()&&route()==='dashboard'&&!document.hidden&&document.querySelector('.metric'))render();},15000);
if (!cfg.apiKey || !cfg.appId || (!emulator && cfg.projectId !== 'nppappointment') || (emulator && cfg.projectId !== 'demo-nppappointment')) {
  window.portalStartup.fail('Firebase configuration is missing or invalid. Contact the portal administrator.');
} else if (window.portalStartup.pending()) {
  const app = initializeApp(cfg);
  auth = getAuth(app);
  fn = getFunctions(app, 'us-central1');
  if (emulator) {
    connectAuthEmulator(auth, 'http://127.0.0.1:9099', { disableWarnings: true });
    connectFunctionsEmulator(fn, '127.0.0.1', 5001);
  }
  onAuthStateChanged(auth, u => {
    if (!ready && !window.portalStartup.complete()) return;
    ready = true;
    if (authBusy) { user = u; me = null; return; }
    user = u;
    me = null;
    ready = true;
    routeRun++;
    root.innerHTML = '<main class="public"><p class="loading">Checking your account…</p></main>';
    render();
  }, () => {
    if (!ready) window.portalStartup.fail('Firebase could not restore the sign-in session. Check your internet connection and reload.');
  });
}
